template.value:
@NotNull(message = "El nombre es obligatorio")
String name,

@NotEmpty(message = "El nombre no puede estar vacío")
String nameNotEmpty,

@NotBlank(message = "El nombre no puede estar vacío")
String nameNotBlank,

@Size(
  min = 2,
  max = 100,
  message = "El nombre debe tener entre 2 y 100 caracteres"
)
String nameSize,

@Email(message = "El correo no tiene un formato válido")
String email,

@Pattern(
  regexp = "\\d{10}",
  message = "El teléfono debe contener 10 dígitos"
)
String phone

@NotNull(message = "La edad es obligatoria")
Integer age,

@Min(
  value = 18,
  message = "La edad debe ser mayor o igual a 18"
)
Integer minAge,

@Max(
  value = 100,
  message = "La edad debe ser menor o igual a 100"
)
Integer maxAge,

@Positive(message = "El valor debe ser mayor a cero")
Integer positiveValue,

@PositiveOrZero(message = "El valor debe ser mayor o igual a cero")
Integer positiveOrZeroValue,

@Negative(message = "El valor debe ser menor a cero")
Integer negativeValue,

@NegativeOrZero(message = "El valor debe ser menor o igual a cero")
Integer negativeOrZeroValue,

// =========================
// BOOLEAN
// =========================

@NotNull(message = "El estado es obligatorio")
Boolean active,

@AssertTrue(message = "El valor debe ser verdadero")
Boolean accepted,

@AssertFalse(message = "El valor debe ser falso")
Boolean rejected

@NotNull(message = "El monto es obligatorio")
BigDecimal amount,

@Positive(message = "El monto debe ser mayor a cero")
BigDecimal positiveAmount,

@PositiveOrZero(message = "El monto debe ser mayor o igual a cero")
BigDecimal positiveOrZeroAmount,

@Negative(message = "El monto debe ser menor a cero")
BigDecimal negativeAmount,

@NegativeOrZero(message = "El monto debe ser menor o igual a cero")
BigDecimal negativeOrZeroAmount,

@DecimalMin(
  value = "0.01",
  message = "El monto debe ser mayor o igual a 0.01"
)
BigDecimal minAmount,

@DecimalMax(
  value = "999999.99",
  message = "El monto debe ser menor o igual a 999999.99"
)
BigDecimal maxAmount,

@Digits(
  integer = 10,
  fraction = 2,
  message = "El monto debe tener máximo 10 enteros y 2 decimales"
)
BigDecimal digitsAmount

@NotNull(message = "La fecha de nacimiento es obligatoria")
LocalDate birthDate,

@Past(message = "La fecha debe ser anterior a la fecha actual")
LocalDate pastDate,

@PastOrPresent(
        message = "La fecha no puede ser posterior a la fecha actual"
)
LocalDate pastOrPresentDate,

@Future(message = "La fecha debe ser posterior a la fecha actual")
LocalDate futureDate,

@FutureOrPresent(
        message = "La fecha no puede ser anterior a la fecha actual"
)
LocalDate futureOrPresentDate,

@Past(
        message = "La fecha y hora deben ser anteriores al momento actual"
)
LocalDateTime pastDateTime,

@Future(
        message = "La fecha y hora deben ser posteriores al momento actual"
)
LocalDateTime futureDateTime

@NotNull(message = "La lista es obligatoria")
List<String> names,

@NotEmpty(message = "La lista no puede estar vacía")
List<String> requiredNames,

@Size(
        min = 1,
        max = 10,
        message = "La lista debe contener entre 1 y 10 elementos"
)
List<String> limitedNames,

List<@NotBlank(message = "El nombre no puede estar vacío") String> validatedNames,

List<@Positive(message = "El ID debe ser mayor a cero") Long> userIds,

Map<String, @NotBlank(message = "El valor no puede estar vacío") String> validatedAttributes,

Map<String, @Valid AddressRequest> addresses,

// =========================
// OBJECT
// =========================

@NotNull(message = "El usuario es obligatorio")
@Valid
UserRequest user,

@Valid
AddressRequest address
